 el.innerHTML=`<section class="area-elisa"><header class="area-hero"><div><div class="area-eyebrow">PSI NEXTGEN / CONTROL Y SEGUIMIENTO</div><h1>Monitoreo microbiológico de áreas</h1><p>Catálogo maestro · Planificación inteligente · Trazabilidad de medios y controles</p></div><span class="area-status">● Catálogo sincronizado</span></header><div class="area-sync-strip"><span class="area-sync-dot"></span>${esc(syncStatus)}</div><div class="area-metrics"><div><small>Puntos configurados</small><b>${points.length}</b></div><div><small>Activos</small><b>${points.filter(p=>p.active).length}</b></div><div><small>Críticos activos</small><b>${points.filter(p=>p.active&&p.criticality==='CRÍTICA').length}</b></div><div><small>Inactivos</small><b>${points.filter(p=>!p.active).length}</b></div></div>${alertsHTML()}<nav class="area-tabs area-tabs-compact">${tabs.map((t,i)=>`<button type="button" data-tab="${tabOrder[i]}" class="${tab===tabOrder[i]?'active':''}">${t}</button>`).join('')}</nav>${tab===3?`<div class="area-management-nav"><button data-management="4" class="${managementView===4?'active':''}">Inventario PDA/PCA</button><button data-management="5" class="${managementView===5?'active':''}">Consolidado</button><button data-management="6" class="${managementView===6?'active':''}">Frecuencias</button><button data-management="7" class="${managementView===7?'active':''}">Criterios técnicos</button></div>`:''}${tab===0?`<div class="area-card"><div class="area-head"><div><h2>Catálogo maestro de puntos</h2><p>Registro y administración de puntos · Los criterios técnicos deben validarse antes del uso operativo.</p></div><div><button type="button" id="area-migrate">⇧ Inicializar puntos originales</button> <button class="area-primary" id="area-add">＋ Nuevo punto</button></div></div><div class="area-filters"><input id="area-search" placeholder="Buscar código, área, medio o método…" value="${esc(query)}" aria-label="Buscar puntos"/><select id="area-type" aria-label="Filtrar por tipo">${['Todos','Ambiente','Superficie','Agua'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select><select id="area-state" aria-label="Filtrar por estado">${['Todos','Activos','Inactivos'].map(t=>`<option ${state===t?'selected':''}>${t}</option>`).join('')}</select><select id="area-size" aria-label="Registros por página">${[10,25,50].map(n=>`<option ${pageSize===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="area-table-wrap"><table><thead><tr><th>Código</th><th>Área / punto</th><th>Tipo</th><th>Criticidad</th><th>Frecuencia</th><th>Medio</th><th>Microorganismo</th><th>Método</th><th>Límites y semáforo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${visible.map(p=>`<tr><td><b>${esc(p.code)}</b></td><td><strong>${esc(p.name)}</strong></td><td>${chip(p)}</td><td><span class="area-pill ${p.criticality==='CRÍTICA'?'red':p.criticality==='ALTA'?'orange':'yellow'}">${esc(p.criticality)}</span>${suggestedCriticality[p.code]&&suggestedCriticality[p.code]!==p.criticality?`<small class="area-suggested">Sugerida: ${esc(suggestedCriticality[p.code])}</small>`:''}</td><td>${esc(p.frequencyDays)} días</td><td><b>${esc(p.type==='Ambiente'?'PDA':'PCA')}</b></td><td>${esc(p.type==='Ambiente'?'Hongos y levaduras':p.type==='Superficie'?'Mesófilos aerobios':p.microorganism)}</td><td>${esc(p.method)}</td><td>${pointLimitsHTML(p)}</td><td><span class="area-pill ${p.active?'green':'gray'}">${p.active?'ACTIVO':'INACTIVO'}</span></td><td class="area-actions"><button data-action="view" data-id="${esc(p.code)}">Consultar</button><button data-action="edit" data-id="${esc(p.code)}">Editar</button><button data-action="${p.active?'deactivate':'reactivate'}" data-id="${esc(p.code)}">${p.active?'Dar de baja':'Reactivar'}</button></td></tr>`).join('')||'<tr><td colspan="11">No se encontraron puntos.</td></tr>'}</tbody></table></div><div class="area-pagination"><span>Mostrando ${visible.length} de ${filtered.length} coincidencias · Página ${page} de ${pages}</span><div><button id="area-prev" ${page===1?'disabled':''}>Anterior</button><button id="area-next" ${page===pages?'disabled':''}>Siguiente</button></div></div></div>`:tab===1?plannerHTML():tab===2?historyHTML():managementHTML()}${successNotice?`<div class="area-success-notice" role="status">✓ ${esc(successNotice)} <button type="button" id="area-success-close" aria-label="Cerrar aviso">×</button></div>`:''}${monitor?`<div class="area-overlay area-monitor-overlay"><div class="area-dialog area-monitor-dialog" role="dialog" aria-modal="true" aria-label="Registrar ejecución de monitoreo"><div class="area-dialog-head"><div><small>PSI · REGISTRO DE EJECUCIÓN</small><h2>Realizar monitoreo</h2><span>${esc(monitor.code)} · ${esc(monitor.name)}</span></div><button type="button" id="area-monitor-x" aria-label="Cerrar ventana">✕</button></div><div class="area-dialog-body"><div class="area-monitor-summary"><strong>${esc(monitor.type)} · ${esc(monitor.type==='Ambiente'?'PDA':'PCA')} · ${esc(monitor.method||'Monitoreo microbiológico')}</strong><span>Frecuencia: ${esc(monitor.frequencyDays)} días · Unidad: ${esc(monitor.type==='Ambiente'?'UFC/15 min':monitor.type==='Superficie'?'UFC/cm²':'UFC/mL')} · Criterios pendientes de validación</span><small>Se genera una lectura para el medio seleccionado.</small></div>${monitor.plannedDate?`<div class="area-planned-notice"><span>Fecha programada automáticamente</span><strong>${fmtDate(monitor.plannedDate)}</strong><small>La fecha real de ejecución se registra por separado; no se modifica el historial.</small></div>`:`<div class="area-planned-notice"><span>Primer monitoreo</span><strong>Sin fecha previa</strong><small>La fecha real se registra a continuación.</small></div>`}<div class="area-monitor-grid"><label>Fecha real de ejecución<input id="area-exec-date" type="date" value="${esc(monitor.date)}"></label><label>Hora real<input id="area-exec-time" type="time" value="${esc(monitor.time)}"></label>${(monitor.type==='Ambiente'?['PDA']:['PCA']).map(m=>`<label>Caja ${esc(m)} liberada y vigente<select id="area-prep-${esc(m)}"><option value="">Seleccione preparación ${esc(m)}</option>${preps.filter(p=>available(p,monitor.date,m)).map(p=>`<option value="${esc(p.id)}">${esc(p.code)} · ${Number(p.count)-Number(p.usedUnits||0)} disponibles · vence ${esc(p.expiry)}</option>`).join('')}</select></label>`).join('')}${(monitor.type==='Ambiente'?['PDA']:['PCA']).filter(m=>!preps.some(p=>available(p,monitor.date,m))).map(m=>`<div class="area-no-stock" role="status"><strong>Sin cajas ${esc(m)} aptas para ${esc(fmtDate(monitor.date))}</strong><p>Revisa preparaciones pendientes de QC o liberación, o inicia una nueva preparación. No se descontará inventario.</p><button type="button" class="area-primary" data-media-shortcut="${esc(m)}">Ir a medios de cultivo · ${esc(m)} →</button></div>`).join('')}<label>Observaciones<input id="area-notes" maxlength="500" placeholder="Condiciones del monitoreo (opcional)"></label></div><div class="area-monitor-hint">Se registra un ensayo y se descuenta exactamente una caja en una transacción. No se aplica conformidad automática.</div>${monitorError?`<div class="area-monitor-error" role="alert">${esc(monitorError)}</div>`:''}</div><div class="area-dialog-actions"><button type="button" id="area-monitor-cancel">Cancelar</button><button type="button" class="area-primary" id="area-monitor-confirm" ${busy?'disabled':''}>${busy?'Guardando…':'Confirmar ejecución y consumir '+('1 caja')}</button></div></div></div>`:''}${modalHTML()}${readingHTML()}</section>`;
 el.querySelector('#area-alert-go')?.addEventListener('click',()=>{tab=1;plannerState='Todos';draw();el.querySelector('.area-planner')?.scrollIntoView({behavior:'smooth',block:'start'});});
